'use client';

import React, { useState } from 'react';
import styles from './dashboard-home.module.css';
import {
    ShoppingBag,
    Users,
    IndianRupee,
    TrendingUp,
    Package
} from 'lucide-react';

export default function AdminDashboardHome() {
    // Mock Stats for Zero-DB Mode
    const stats = {
        totalOrders: 154,
        totalRevenue: 42500,
        totalCustomers: 89,
        activeProducts: 12,
        topSelling: [
            { name: 'Sankara Karuvadu', sales: 45 },
            { name: 'Nethili Karuvadu', sales: 32 },
            { name: 'Vanjiram Karuvadu', sales: 18 }
        ]
    };

    return (
        <div className={styles.container}>
            <div className={styles.statsGrid}>
                <div className={styles.statCard}>
                    <div className={`${styles.icon} ${styles.blue}`}>
                        <ShoppingBag size={24} />
                    </div>
                    <div className={styles.statInfo}>
                        <p>Total Orders</p>
                        <h3>{stats.totalOrders}</h3>
                    </div>
                </div>
                <div className={styles.statCard}>
                    <div className={`${styles.icon} ${styles.green}`}>
                        <IndianRupee size={24} />
                    </div>
                    <div className={styles.statInfo}>
                        <p>Total Revenue</p>
                        <h3>₹{stats.totalRevenue}</h3>
                    </div>
                </div>
                <div className={styles.statCard}>
                    <div className={`${styles.icon} ${styles.orange}`}>
                        <Users size={24} />
                    </div>
                    <div className={styles.statInfo}>
                        <p>Customers</p>
                        <h3>{stats.totalCustomers}</h3>
                    </div>
                </div>
                <div className={styles.statCard}>
                    <div className={`${styles.icon} ${styles.purple}`}>
                        <Package size={24} />
                    </div>
                    <div className={styles.statInfo}>
                        <p>Active Products</p>
                        <h3>{stats.activeProducts}</h3>
                    </div>
                </div>
            </div>

            <div className={styles.chartsGrid}>
                <div className={styles.chartCard}>
                    <h4>Sales Overview</h4>
                    <div className={styles.placeholderChart}>
                        <TrendingUp size={48} color="#e2e8f0" />
                        <p>Sales trend showing consistent growth</p>
                    </div>
                </div>
                <div className={styles.chartCard}>
                    <h4>Top Selling Items</h4>
                    <ul className={styles.topList}>
                        {stats.topSelling.map((item: any, idx: number) => (
                            <li key={idx}>
                                <span>{item.name}</span>
                                <strong>{item.sales} Kg</strong>
                            </li>
                        ))}
                    </ul>
                </div>
            </div>
        </div>
    );
}
